if (begin == end) {
    _min = Point3d(0.0, 0.0, 0.0);
    _max = Point3d(0.0, 0.0, 0.0);
    return;
}

_min = *begin;
_max = *begin;

for (auto it = begin + 1; it != end; ++it) {
    const Point3d& p = *it;
    if (p.x() < _min.x()) _min.setX(p.x());
    if (p.y() < _min.y()) _min.setY(p.y());
    if (p.z() < _min.z()) _min.setZ(p.z());

    if (p.x() > _max.x()) _max.setX(p.x());
    if (p.y() > _max.y()) _max.setY(p.y());
    if (p.z() > _max.z()) _max.setZ(p.z());
}

